-- Administration (FR-ADM-001, 002, 004) and consent records (FR-AUD-004), ADR 011.

-- ============ Part 1: tables (generated by prisma migrate diff) ============
-- AlterTable
ALTER TABLE "organizations" ADD COLUMN     "att_disconnect_grace_seconds" INTEGER NOT NULL DEFAULT 120,
ADD COLUMN     "att_idle_seconds" INTEGER NOT NULL DEFAULT 300,
ADD COLUMN     "att_max_session_seconds" INTEGER NOT NULL DEFAULT 50400,
ADD COLUMN     "att_missed_heartbeat_seconds" INTEGER NOT NULL DEFAULT 90,
ADD COLUMN     "att_paid_break_minutes" INTEGER NOT NULL DEFAULT 60,
ADD COLUMN     "att_pause_seconds" INTEGER NOT NULL DEFAULT 900,
ADD COLUMN     "retention_notifications_days" INTEGER NOT NULL DEFAULT 365,
ADD COLUMN     "retention_presence_days" INTEGER NOT NULL DEFAULT 90;

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "custom_role_id" UUID;

-- AlterTable
ALTER TABLE "monitoring_consents" ADD COLUMN     "consent_type" VARCHAR(20) NOT NULL DEFAULT 'MONITORING',
ADD COLUMN     "granted" BOOLEAN NOT NULL DEFAULT true;

-- CreateTable
CREATE TABLE "org_roles" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "org_id" UUID NOT NULL,
    "name" VARCHAR(80) NOT NULL,
    "description" TEXT NOT NULL DEFAULT '',
    "base_role" VARCHAR(50) NOT NULL,
    "added_permissions" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "removed_permissions" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "created_by" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "org_roles_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "org_roles_org_id_name_key" ON "org_roles"("org_id", "name");

-- AddForeignKey
ALTER TABLE "users" ADD CONSTRAINT "users_custom_role_id_fkey" FOREIGN KEY ("custom_role_id") REFERENCES "org_roles"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "org_roles" ADD CONSTRAINT "org_roles_org_id_fkey" FOREIGN KEY ("org_id") REFERENCES "organizations"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- ============ Part 2: rules, security (hand-written) ============

-- FR-ADM-001: SRS 6.4 ranges, enforced by the database as well as the API.
ALTER TABLE organizations
  ADD CONSTRAINT organizations_att_missed_heartbeat_check CHECK (att_missed_heartbeat_seconds BETWEEN 60 AND 180),
  ADD CONSTRAINT organizations_att_disconnect_grace_check CHECK (att_disconnect_grace_seconds BETWEEN 30 AND 300),
  ADD CONSTRAINT organizations_att_idle_check CHECK (att_idle_seconds BETWEEN 120 AND 1800),
  ADD CONSTRAINT organizations_att_pause_check CHECK (att_pause_seconds BETWEEN 300 AND 3600 AND att_pause_seconds > att_idle_seconds),
  ADD CONSTRAINT organizations_att_max_session_check CHECK (att_max_session_seconds BETWEEN 28800 AND 64800),
  ADD CONSTRAINT organizations_att_paid_break_check CHECK (att_paid_break_minutes BETWEEN 0 AND 240),
  ADD CONSTRAINT organizations_retention_presence_check CHECK (retention_presence_days BETWEEN 30 AND 730),
  ADD CONSTRAINT organizations_retention_notifications_check CHECK (retention_notifications_days BETWEEN 30 AND 1825);

ALTER TABLE org_roles
  ADD CONSTRAINT org_roles_base_role_check CHECK (base_role IN ('ADMIN', 'HR_MANAGER', 'HR', 'MANAGER', 'TEAM_LEAD', 'EMPLOYEE', 'SUBCONTRACTOR', 'INTERN', 'AUDITOR')),
  ADD CONSTRAINT org_roles_name_check CHECK (length(btrim(name)) BETWEEN 2 AND 80);

ALTER TABLE monitoring_consents
  ADD CONSTRAINT monitoring_consents_type_check CHECK (consent_type IN ('MONITORING', 'RECORDING', 'AI'));

ALTER TABLE org_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE org_roles FORCE ROW LEVEL SECURITY;
CREATE POLICY org_roles_org_policy ON org_roles FOR ALL
  USING (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid)
  WITH CHECK (org_id = NULLIF(current_setting('app.org_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON org_roles TO hrvo_app;

-- A custom role and its users must belong to the same organisation.
CREATE FUNCTION fn_user_custom_role_same_org() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.custom_role_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM org_roles r WHERE r.id = NEW.custom_role_id AND r.org_id = NEW.org_id) THEN
    RAISE EXCEPTION 'custom role belongs to another organisation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER users_custom_role_same_org BEFORE INSERT OR UPDATE OF custom_role_id ON users
  FOR EACH ROW EXECUTE FUNCTION fn_user_custom_role_same_org();

-- Scheduled jobs read the retention settings too (still ids and settings only).
DROP FUNCTION fn_list_orgs_for_jobs();
CREATE FUNCTION fn_list_orgs_for_jobs()
RETURNS TABLE (id UUID, timezone VARCHAR, task_acceptance_escalation_hours INT, timesheet_submit_due_days INT, retention_presence_days INT, retention_notifications_days INT)
SECURITY DEFINER
SET search_path = public
LANGUAGE sql STABLE AS $$
  SELECT o.id, o.timezone, o.task_acceptance_escalation_hours, o.timesheet_submit_due_days, o.retention_presence_days, o.retention_notifications_days
  FROM organizations o ORDER BY o.id;
$$;
REVOKE ALL ON FUNCTION fn_list_orgs_for_jobs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fn_list_orgs_for_jobs() TO hrvo_app;

-- FR-ADM-004: notifications are pruned by the retention role; the app still cannot delete them.
GRANT SELECT, DELETE ON notifications TO hrvo_retention;
